def largest_prime_factor(n: int):
    def is_prime(num: int) -> bool:
        """Check if num is prime."""
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    largest = None
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0 and n > 1:
            if is_prime(i):
                largest = i
            n //= i

    if n > 1:
        largest = n

    return largest

