def fibfib(n: int) -> int:
    if n <= 0:
        return 0
    memo = {0: 0, 1: 0, 2: 1}

    def memoized_fibfib(k: int):
        if k in memo:
            return memo[k]
        else:
            result = memoized_fibfib(k - 1) + memoized_fibfib(k - 2) + memoized_fibfib(k - 3)
            memo[k] = result
            return result

