def smallest_change(arr):
    # Create a counter for each number in the array
    counters = {}
    for num in arr:
        if num in counters:
            counters[num] += 1
        else:
            counters[num] = 1

    # Count odd counts. Each position can fix n-i of arrays by replacing  numbers in it.
    odd_cnt = sum(n & 1 for n in counters.values())

    return max(0, odd_cnt - 1)


