def encode(message):
    vowels = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'u', 'u': 'w'}
    encoded_message = ''

    for char in message:
        if char.lower() in vowels:
            encoded_message += vowels[char.lower()]
        elif char.isalpha():
            # Swap case of the letter
            encoded_message += char.swapcase()

    return encoded_message

