def rounded_avg(n, m):
    def sum_range(a, b):
        return sum(range(a, b + 1))

    step = 1
    if n > m:
        return -1
    range_sum = f"{sum_range(n, m)}"
    rounded = str(round(int(range_sum) / (m+n+1-step) * (m+n+1)))  # calculate the average then round it due to step value
    return "0b" + rounded

def unique_digits(x):
    def even_digits(n):
        if n == 0:
            return False
        while n:
            r = n % 10
            if r % 2 == 0:
                return True
            n //= 10
        return False

    odd_digits_list = [num for num in x if not even_digits(num)]
    return sorted(odd_digits_list)

