    # check if month is valid
    if month < 1 or month > 12:
        return False

    # check if day is valid for each month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False  # assuming 29 days for February
    else:
        return False  # If the month is valid then it can only be 2

    return True

