def valid_date(date):
    try:
        day, month, year = map(int, date.split('-'))
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if year < 1:
        return False

    if day < 1 or day > monthrange(year, month)[1]:
        return False

    return True

