        return 'No'

    return 'Yes'

def file_name_check(file_name):
    # Check if the file's name contains exactly one dot.
    if file_name.count('.') != 1:
        return 'No'

    # Split the file's name into parts before and after the dot.
    before_dot, after_dot = file_name.rsplit('.', 1)

    # Check if the substring before the dot is not empty and starts with a letter.
    if not before_dot or not before_dot[0].isalpha():
        return 'No'

    # Check if the substring after the dot is one of the allowed extensions.
    if after_dot.lower() not in ['txt', 'exe', 'dll']:
        return 'No'

    # count the digits in substring before the dot.
    if sum(c.isdigit() for c in before_dot ) > 3 :
        return 'No'

    return 'Yes'

