    if 1 <= number <= 1000:
        result = ''
        for numeral in sorted(RomanNumerals.keys(), reverse=True):
            while number >= numeral:
                result += RomanNumerals[numeral]
                number -= numeral
        return result.lower()
    else:
        raise ValueError("Input is not within the valid range of 1 to 1000.")

