def generate_integers(a, b):
    def is_even(n):
        return n % 2 == 0

    def get_digits(n):
        digits = [int(d) for d in str(n)]
        return [d for d in digits if is_even(d)]

    smaller = min(a, b)
    larger = max(a, b)

    even_digits_all_nums = [get_digits(n) for n in range(smaller, larger+1)]

    result = []
    for n in even_digits_all_nums:
        for d in n:
            for rd in result:
                if rd == d:
                    result.remove(rd)
        result.extend(n)         

    return sorted(set(result))

